"Create the invoice and send it to the guest": "ইনভয়েস তৈরি করে গেস্টকে পাঠান",
"Invoice number assigned automatically. Direct bookings get it on WhatsApp, platform bookings by email. Same switch as the invoice settings in Invoices & Receipts.": "ইনভয়েস নম্বর নিজে থেকে দেওয়া হয়। ডাইরেক্ট বুকিং WhatsApp-এ, প্ল্যাটফর্ম বুকিং ইমেইলে পায়। ইনভয়েস ও রসিদের ইনভয়েস সেটিংসের একই সুইচ।",
"Auto": "অটো",
"Payment arrives for a booking": "বুকিংয়ের পেমেন্ট এসেছে",
"Create the receipt and send it to the guest": "রসিদ তৈরি করে গেস্টকে পাঠান",
"The receipt is created as soon as the payment is recorded and sent at 6:00 PM that day, on the same channel as the invoice. Same switch as the receipt settings in Invoices & Receipts.": "পেমেন্ট নথিভুক্ত হওয়ার সাথে সাথে রসিদ তৈরি হয় এবং সেদিন সন্ধ্যা 6টায় ইনভয়েসের একই চ্যানেলে পাঠানো হয়। ইনভয়েস ও রসিদের রসিদ সেটিংসের একই সুইচ।",
"Staff record an expense they paid personally": "স্টাফ নিজের টাকায় করা খরচ নথিভুক্ত করেন",
"Ask the owner to approve the claim": "দাবি অনুমোদনের জন্য মালিককে বলুন",
"The claim stays pending until an account owner approves it. Approval cannot be given to other roles.": "অ্যাকাউন্ট মালিক অনুমোদন না করা পর্যন্ত দাবি অপেক্ষমাণ থাকে। অন্য ভূমিকাকে অনুমোদনের অধিকার দেওয়া যায় না।",
"A booking is made for arrival today": "আজ আগমনের একটি বুকিং হয়েছে",
"Alert the ops manager and create an urgent turnover task": "অপারেশনস ম্যানেজারকে জানান ও জরুরি টার্নওভার কাজ তৈরি করুন",
"If the unit still needs cleaning, the turnover for the property's housekeeper is marked urgent and due 15 minutes before arrival. If it is already clean, a pre-arrival inspection is created instead. The booking shows under Same-day bookings on the dashboard.": "ইউনিটে এখনো পরিষ্কার দরকার হলে প্রপার্টির হাউসকিপারের টার্নওভার জরুরি হিসেবে চিহ্নিত হয় এবং আগমনের 15 মিনিট আগে শেষ করতে হয়। আগেই পরিষ্কার থাকলে আগমনের আগের পরিদর্শন তৈরি হয়। বুকিংটি ড্যাশবোর্ডে একই দিনের বুকিংয়ের নিচে দেখা যায়।",
"A guest opens the door code in the guest app": "গেস্ট অ্যাপে গেস্ট দরজার কোড খোলেন",
"Show the house rules first and require acceptance": "আগে ঘরের নিয়ম দেখান ও মেনে নেওয়া বাধ্যতামূলক করুন",
"The guest ticks agree and types their name. The door code stays hidden until rules are accepted and ID is verified.": "গেস্ট \"রাজি\" টিক দিয়ে নাম লেখেন। নিয়ম মেনে নেওয়া ও আইডি যাচাই না হওয়া পর্যন্ত দরজার কোড লুকানো থাকে।",
"A guest reports damage in the guest app": "গেস্ট অ্যাপে গেস্ট ক্ষতির রিপোর্ট করেন",
"Create a maintenance task with the photos and alert maintenance": "ছবিসহ রক্ষণাবেক্ষণের কাজ তৈরি করুন ও রক্ষণাবেক্ষণকে জানান",
"Every damaged item needs a photo. The task is assigned to maintenance and linked to the booking for any deposit claim.": "প্রতিটি ক্ষতিগ্রস্ত জিনিসের ছবি লাগবে। কাজটি রক্ষণাবেক্ষণকে দেওয়া হয় এবং জামানতের দাবির জন্য বুকিংয়ের সাথে যুক্ত থাকে।",
"A guest checks out": "একজন গেস্ট চেক-আউট করেন",
"Create a turnover clean for the property's housekeeper": "প্রপার্টির হাউসকিপারের জন্য টার্নওভার পরিষ্কার তৈরি করুন",
"Due 15 minutes before the next check-in, or 3:00 PM if nobody arrives that day.": "পরের চেক-ইনের 15 মিনিট আগে, বা সেদিন কেউ না এলে বিকেল 3টায় শেষ করতে হবে।",
