"No house rules yet. Add at least one so guests have something to accept.": "এখনো কোনো ঘরের নিয়ম নেই। অন্তত একটি যোগ করুন যাতে গেস্টদের মেনে নেওয়ার মতো কিছু থাকে।",
"Getting in": "ভেতরে ঢোকা",
"Steps shown with the address and parking. {lock} becomes the unit's lock brand. Pick a unit to show a step only there.": "ঠিকানা ও পার্কিংয়ের সাথে দেখানো ধাপ। {lock} হয় ইউনিটের লকের ব্র্যান্ড। শুধু একটি ইউনিটে ধাপ দেখাতে সেটি বাছুন।",
"Describe one step.": "একটি ধাপ বর্ণনা করুন।",
"No steps yet. Guests see the address, parking and their door code.": "এখনো কোনো ধাপ নেই। গেস্টরা ঠিকানা, পার্কিং ও তাঁদের দরজার কোড দেখেন।",
