"Translation is not set up on the server yet (ANTHROPIC_API_KEY in Vercel).": "সার্ভারে অনুবাদ এখনো সেটআপ হয়নি (Vercel-এ ANTHROPIC_API_KEY)।",
"Translation": "অনুবাদ",
"Booking sites": "বুকিং সাইট",
"Booking email": "বুকিং ইমেইল",
