"came in.": "এসেছে।",
"Facebook is still loading. Try again in a moment.": "Facebook এখনো লোড হচ্ছে। একটু পরে আবার চেষ্টা করুন।",
"Waiting for Facebook…": "Facebook-এর অপেক্ষা…",
