". WhatsApp did not share the earlier chats; new messages come in.": "। WhatsApp আগের চ্যাট শেয়ার করেনি; নতুন বার্তা আসে।",
"WhatsApp disconnected": "WhatsApp বিচ্ছিন্ন",
"is larger than 25 MB, the WhatsApp limit": "25 MB-এর বেশি, যা WhatsApp-এর সীমা",
