"Microphone not available": "মাইক্রোফোন পাওয়া যাচ্ছে না",
"You can still send a voice note: choose an audio file, for example a recording made with your phone's voice recorder. It is sent as a voice message the guest can play.": "তবুও ভয়েস নোট পাঠাতে পারেন: একটি অডিও ফাইল বাছুন, যেমন ফোনের ভয়েস রেকর্ডারে করা রেকর্ডিং। এটি গেস্ট চালাতে পারেন এমন ভয়েস বার্তা হিসেবে যায়।",
"Choose audio file": "অডিও ফাইল বাছুন",
"This browser cannot record audio on this page": "এই ব্রাউজার এই পেজে অডিও রেকর্ড করতে পারে না",
"because the page is not served securely (https)": "কারণ পেজটি নিরাপদভাবে (https) দেওয়া হচ্ছে না",
"This browser cannot record audio here": "এই ব্রাউজার এখানে অডিও রেকর্ড করতে পারে না",
"Microphone access was blocked here. In the live app the browser asks once for permission; in this preview, recording is not allowed.": "এখানে মাইক্রোফোনের অ্যাক্সেস আটকানো হয়েছে। লাইভ অ্যাপে ব্রাউজার একবার অনুমতি চায়; এই প্রিভিউতে রেকর্ডিংয়ের অনুমতি নেই।",
"No microphone was found on this device.": "এই ডিভাইসে কোনো মাইক্রোফোন পাওয়া যায়নি।",
"The microphone is being used by another app.": "মাইক্রোফোনটি অন্য একটি অ্যাপ ব্যবহার করছে।",
"This page is not allowed to use the microphone.": "এই পেজে মাইক্রোফোন ব্যবহারের অনুমতি নেই।",
"The microphone could not be started": "মাইক্রোফোন চালু করা যায়নি",
"Voice notes are limited to 5 minutes, so this one was sent": "ভয়েস নোট 5 মিনিটে সীমিত, তাই এটি পাঠানো হয়েছে",
"Voice note too short. Hold on for at least a second.": "ভয়েস নোট খুব ছোট। অন্তত এক সেকেন্ড ধরে রাখুন।",
"Voice note added for your team": "আপনার টিমের জন্য ভয়েস নোট যোগ হয়েছে",
"Voice note": "ভয়েস নোট",
") sent to": ") পাঠানো হয়েছে:",
"Recording deleted": "রেকর্ডিং মুছে ফেলা হয়েছে",
"No quick reply matches. Press Esc to keep typing.": "কোনো দ্রুত উত্তর মেলেনি। লিখে যেতে Esc চাপুন।",
"Door codes are not part of your access, so the code was left out": "দরজার কোড আপনার অ্যাক্সেসের অংশ নয়, তাই কোডটি বাদ দেওয়া হয়েছে",
"has not verified their ID yet, so the door code was left out": "এখনো আইডি যাচাই করেননি, তাই দরজার কোড বাদ দেওয়া হয়েছে",
"There is no greeting message for this building yet": "এই বিল্ডিংয়ের এখনো কোনো স্বাগত বার্তা নেই",
"gets now": "এখন পাবেন",
"Door codes are not part of your access, so they show as hidden here. The guest gets the real code.": "দরজার কোড আপনার অ্যাক্সেসের অংশ নয়, তাই এখানে লুকানো দেখায়। গেস্ট আসল কোড পান।",
"Greeting sent to": "স্বাগত বার্তা পাঠানো হয়েছে:",
"The greeting was not sent. Please try again.": "স্বাগত বার্তা পাঠানো হয়নি। আবার চেষ্টা করুন।",
