"Edit before sending": "পাঠানোর আগে সম্পাদনা",
"This greeting has a door code or private part you cannot see, so it cannot be edited here. Use Send greeting to send it as written.": "এই স্বাগত বার্তায় দরজার কোড বা এমন গোপন অংশ আছে যা আপনি দেখতে পারেন না, তাই এখানে সম্পাদনা করা যায় না। লেখা অনুযায়ী পাঠাতে স্বাগত বার্তা পাঠান ব্যবহার করুন।",
