"Your first message goes by {x}. Use a quick reply below or type a message.": "আপনার প্রথম মেসেজ {x} মাধ্যমে যায়। নিচে দ্রুত উত্তর ব্যবহার করুন বা মেসেজ টাইপ করুন।",
"WhatsApp only takes a reply after the guest has written to your WhatsApp number. Share the number in your booking confirmation{x}": "অতিথি আপনার WhatsApp নম্বরে লেখার পরেই WhatsApp উত্তর নেয়। বুকিং নিশ্চিতকরণে নম্বরটি শেয়ার করুন{x}",
"Your first message goes to {x} on WhatsApp. Use a quick reply below or type a message.": "আপনার প্রথম মেসেজ WhatsApp-এ {x}-এর কাছে যায়। নিচে দ্রুত উত্তর ব্যবহার করুন বা মেসেজ টাইপ করুন।",
