"This {x} booking was entered by hand, so it is not linked to the {x} chat. Message the guest from {x} itself{x}": "এই {x} বুকিং হাতে দেওয়া, তাই এটি {x} চ্যাটের সাথে যুক্ত নয়। অতিথিকে {x} থেকেই মেসেজ করুন{x}",
