"Replace \"{x}\" before sending, or use Send greeting, which sends the real code.": "পাঠানোর আগে \"{x}\" বদলান, বা স্বাগত বার্তা পাঠান ব্যবহার করুন, যা আসল কোড পাঠায়।",
