"Nearby places belong to a building. Add your building in Properties (Buildings & unit types), then pick the places guests should know about.": "কাছাকাছি জায়গা একটি বিল্ডিংয়ের অধীনে। প্রপার্টি (বিল্ডিং ও ইউনিট টাইপ)-এ বিল্ডিং যোগ করুন, তারপর অতিথিদের জানা দরকার এমন জায়গা বেছে নিন।",
