"Orbique creates the workspace and the owner's sign-in with a temporary password for you to send them. If the email already has an account, they are added as the owner without changing their password.": "Orbique ওয়ার্কস্পেস ও মালিকের সাইন-ইন অস্থায়ী পাসওয়ার্ডসহ তৈরি করে, যা আপনি তাদের পাঠাবেন। ইমেইলে আগে থেকে অ্যাকাউন্ট থাকলে, পাসওয়ার্ড না বদলে তাদের মালিক হিসেবে যোগ করা হয়।",
