"already has an Orbique account, so they sign in with their usual password and will find {x} in their workspace list.": "আগে থেকেই Orbique অ্যাকাউন্ট আছে, তাই তারা সাধারণ পাসওয়ার্ডে সাইন ইন করেন এবং ওয়ার্কস্পেস তালিকায় {x} পাবেন।",
