"sold{x} than with today's prices.": "বিক্রি{x} আজকের দামের তুলনায়।",
"{x} to clean, with more wear and more guest messages.": "{x} পরিষ্কার করতে, বেশি ক্ষয় ও বেশি অতিথি বার্তা।",
"{x}: less cleaning, wear and guest messages.": "{x}: কম পরিষ্কার, ক্ষয় ও অতিথি বার্তা।",
"Moves all {x} nights with a price today": "আজ দাম থাকা সব {x}টি রাত সরায়",
"Moves {x} of the {x} nights with a price today": "আজ দাম থাকা {x}টি রাতের মধ্যে {x}টি সরায়",
"by {x} or more, and the forecast is less sure about prices guests have not seen.": "{x} বা বেশি, এবং অতিথিরা দেখেননি এমন দামে পূর্বাভাস কম নিশ্চিত।",
"Still covers its costs if demand is {x}% weaker.": "চাহিদা {x}% দুর্বল হলেও খরচ মেটায়।",
"If demand is {x}% weaker, the unit about breaks even.": "চাহিদা {x}% দুর্বল হলে ইউনিট প্রায় সমান-সমান থাকে।",
"Still makes about {x} a month if demand is {x}% weaker.": "চাহিদা {x}% দুর্বল হলেও মাসে প্রায় {x} আয় করে।",
"If demand is {x}% weaker, profit falls to about {x} a month.": "চাহিদা {x}% দুর্বল হলে লাভ মাসে প্রায় {x}-এ নামে।",
"If demand is {x}% weaker, the unit loses about {x} a month.": "চাহিদা {x}% দুর্বল হলে ইউনিটের মাসে প্রায় {x} লোকসান হয়।",
"Relies on late bookings more than today's prices: {x} of the nights it sells usually book in the last {x} days before arrival.": "আজকের দামের চেয়ে দেরির বুকিংয়ে বেশি নির্ভর করে: এর বিক্রিত রাতের {x} সাধারণত আগমনের আগের শেষ {x} দিনে বুক হয়।",
"Most likely profit is about {x} a month.": "সবচেয়ে সম্ভাব্য লাভ মাসে প্রায় {x}।",
