"In a good run (about 1 in 10) the loss could be as small as {x} a month.": "ভালো সময়ে (প্রায় 10-এ 1) লোকসান মাসে মাত্র {x} হতে পারে।",
"In a bad run (about 1 in 10) profit could be as low as {x} a month.": "খারাপ সময়ে (প্রায় 10-এ 1) লাভ মাসে {x}-এ নামতে পারে।",
"In a bad run (about 1 in 10) the unit could lose {x} a month or more.": "খারাপ সময়ে (প্রায় 10-এ 1) ইউনিটের মাসে {x} বা বেশি লোকসান হতে পারে।",
