"loses about {x}": "প্রায় {x} লোকসান করে",
"a month, about {x} short{x}": "মাসে, প্রায় {x} কম{x}",
"; the recommended plan still has {x} of reaching it.": "; প্রস্তাবিত প্ল্যানের এখনো এতে পৌঁছানোর {x} আছে।",
"On average, no plan covers all costs in these dates. The best one loses about {x} a month.": "গড়ে, এই তারিখগুলোতে কোনো প্ল্যান সব খরচ মেটায় না। সবচেয়ে ভালোটির মাসে প্রায় {x} লোকসান।",
", costs would need to be about {x} a month lower{x}": ", খরচ মাসে প্রায় {x} কম হতে হবে{x}",
"; more bookings alone would not do it, as even selling every open night at those prices {x}": "; শুধু বেশি বুকিংয়ে হবে না, কারণ ওই দামে সব খালি রাত বিক্রি হলেও {x}",
", or about {x}% more bookings at the same prices.": ", বা একই দামে প্রায় {x}% বেশি বুকিং।",
"There is no {x} or {x} plan: both look for prices that cover all costs, and on average none does in these dates.": "কোনো {x} বা {x} প্ল্যান নেই: দুটোই এমন দাম খোঁজে যা সব খরচ মেটায়, আর এই তারিখগুলোতে গড়ে কোনোটাই মেটায় না।",
"make about {x}": "প্রায় {x} আয় করে",
", short of the {x} target.": ", {x} লক্ষ্যের চেয়ে কম।",
"How much guests react to price is the least certain part of the forecast. If they react less than assumed, the most profitable prices would be {x}": "অতিথিরা দামে কতটা সাড়া দেন তা পূর্বাভাসের সবচেয়ে অনিশ্চিত অংশ। তারা অনুমানের চেয়ে কম সাড়া দিলে সবচেয়ে লাভজনক দাম হবে {x}",
"than today's rather than {x}": "আজকের চেয়ে, {x}-এর বদলে",
". The difference in profit between the two is about {x} a month.": "। দুটির মধ্যে লাভের পার্থক্য মাসে প্রায় {x}।",
